    #[must_use]
    pub const fn affinity(&self) -> Option<&str> {
        match &self.affinity {
            Some(s) => Some(s.as_str()),
            None => None,
        }
    }

    /// Substrate-canonical per-`:placement` `:estrategia` distribution-
